/* =====================================================================
   Projeto : SQL Help Desk - Estudos de SQL Server
   Script  : 02_inserir_dados.sql
   Objetivo: Popular o banco HelpDeskTI com dados fictícios.

   Empresa fictícia : Aurora Distribuidora (todos os nomes, e-mails e
                      dados são inventados)
   "Data atual" da base: 24/11/2026 18:00 - os chamados em aberto
                      foram criados considerando essa data.

   Os IDs são informados explicitamente (SET IDENTITY_INSERT ON) para
   que os dados sejam sempre os mesmos e fáceis de consultar.
   Depois da carga, novos INSERTs voltam a usar a numeração automática.
   ===================================================================== */

USE HelpDeskTI;
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;   -- se qualquer INSERT falhar, a transação inteira é desfeita

BEGIN TRANSACTION;


/* ---- Departamentos (9 registros) ---- */
SET IDENTITY_INSERT dbo.Departamentos ON;


SET IDENTITY_INSERT dbo.Departamentos OFF;

/* ---- Colaboradores (32 registros) ---- */
SET IDENTITY_INSERT dbo.Colaboradores ON;


SET IDENTITY_INSERT dbo.Colaboradores OFF;

/* ---- Tecnicos (7 registros) ---- */
SET IDENTITY_INSERT dbo.Tecnicos ON;


SET IDENTITY_INSERT dbo.Tecnicos OFF;

/* ---- Categorias (8 registros) ---- */
SET IDENTITY_INSERT dbo.Categorias ON;


SET IDENTITY_INSERT dbo.Categorias OFF;

/* ---- Equipamentos (54 registros) ---- */
SET IDENTITY_INSERT dbo.Equipamentos ON;


SET IDENTITY_INSERT dbo.Equipamentos OFF;

/* ---- Chamados (96 registros) ---- */
SET IDENTITY_INSERT dbo.Chamados ON;


SET IDENTITY_INSERT dbo.Chamados OFF;

/* ---- Interacoes (224 registros) ---- */
SET IDENTITY_INSERT dbo.Interacoes ON;


SET IDENTITY_INSERT dbo.Interacoes OFF;

COMMIT TRANSACTION;
GO

PRINT N'Dados inseridos com sucesso. Próximo passo: 03_verificar_carga.sql';
GO
